import re
def cell_changes(fr_before, fr_after):
    ba = fr_before.ascii.split('\n'); bb = fr_after.ascii.split('\n')
    out = []
    for r in range(len(ba)):
        if r <= 2: continue
        row_a, row_b = ba[r], bb[r]
        for c,ch in enumerate(row_a):
            if row_b[c] != ch:
                out.append(f"{ch}>{row_b[c]} @({r},{c})")
    return out

